() => {
  // The linear-light form injected onto the demo's own hosts: one pair of SVG
  // reference filters for the whole document, the same two widths, so the reading
  // is the form's cost and not a filter per element.
  const SHARP = 1.25, HEAVY = 1.25 * Math.sqrt(63);
  const dpr = window.devicePixelRatio;
  const MASK = false;
  const NS = 'http://www.w3.org/2000/svg';
  const defs = document.createElementNS(NS, 'svg');
  defs.setAttribute('width', '0'); defs.setAttribute('height', '0');
  defs.style.position = 'absolute';
  for (const [id, sigma] of [['w16RefSharp', SHARP], ['w16RefHeavy', HEAVY]]) {
    const f = document.createElementNS(NS, 'filter');
    f.setAttribute('id', id);
    f.setAttribute('x', '-50%'); f.setAttribute('y', '-50%');
    f.setAttribute('width', '200%'); f.setAttribute('height', '200%');
    f.setAttribute('color-interpolation-filters', 'linearRGB');
    const b = document.createElementNS(NS, 'feGaussianBlur');
    b.setAttribute('stdDeviation', String(sigma));
    f.append(b);
    const c = document.createElementNS(NS, 'feColorMatrix');
    c.setAttribute('type', 'saturate'); c.setAttribute('values', '1.5');
    f.append(c);
    defs.append(f);
  }
  document.body.append(defs);
  for (const el of [...document.querySelectorAll('*')]) {
    const cs = getComputedStyle(el);
    if (cs.backdropFilter === 'none') continue;
    el.style.backdropFilter = 'none';
    el.style.webkitBackdropFilter = 'none';
    el.style.isolation = 'isolate';
    const mk = (id) => {
      const d = document.createElement('div');
      d.style.cssText = 'position:absolute;inset:0;z-index:-1;border-radius:inherit;pointer-events:none';
      d.style.backdropFilter = `url(#${id})`;
      return d;
    };
    el.append(mk('w16RefSharp'));
    const heavy = mk('w16RefHeavy');
    if (MASK) {
      const b = el.getBoundingClientRect();
      const c = document.createElement('canvas');
      c.width = Math.max(1, Math.round(b.width * dpr));
      c.height = Math.max(1, Math.round(b.height * dpr));
      const ctx = c.getContext('2d');
      const g = ctx.createLinearGradient(0, 0, 0, c.height);
      g.addColorStop(0, 'rgba(255,255,255,0.48)');
      g.addColorStop(0.5, 'rgba(255,255,255,0.52)');
      g.addColorStop(1, 'rgba(255,255,255,0.48)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, c.width, c.height);
      const u = `url("${c.toDataURL()}")`;
      heavy.style.maskImage = u; heavy.style.webkitMaskImage = u;
      heavy.style.maskMode = 'alpha'; heavy.style.maskSize = '100% 100%';
      heavy.style.maskRepeat = 'no-repeat';
    } else heavy.style.opacity = '0.489';
    el.append(heavy);
  }
}

